/**
 * 简单的 XOR + Base64 加密工具
 * 用于加密存储管理员密码到 data/settings.json，避免明文存在公开 GitHub 仓库
 * 注意：这只是简单混淆，不是真正的安全加密，防止的是"不小心看到"而非"专业破解"
 */

// 固定密钥（前后端一致即可，纯前端环境下密钥必然暴露，这里只做混淆）
const XOR_KEY = 'led-light-admin-2026';

/**
 * XOR 加密 + Base64 编码
 */
export function encryptPassword(password: string): string {
  if (!password) return '';
  let result = '';
  for (let i = 0; i < password.length; i++) {
    result += String.fromCharCode(password.charCodeAt(i) ^ XOR_KEY.charCodeAt(i % XOR_KEY.length));
  }
  // 用 btoa + encodeURIComponent 处理中文/特殊字符
  return btoa(unescape(encodeURIComponent(result)));
}

/**
 * Base64 解码 + XOR 解密
 */
export function decryptPassword(encrypted: string): string {
  if (!encrypted) return '';
  try {
    const decoded = decodeURIComponent(escape(atob(encrypted)));
    let result = '';
    for (let i = 0; i < decoded.length; i++) {
      result += String.fromCharCode(decoded.charCodeAt(i) ^ XOR_KEY.charCodeAt(i % XOR_KEY.length));
    }
    return result;
  } catch {
    return '';
  }
}
